import{_ as p,r as n,o,c as l,e as s,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const _=JSON.parse('{"title":"{% if %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Правила выражений","slug":"правила-выражении","link":"#правила-выражении","children":[]}],"relativePath":"3.x/ru/markup/tag/if.md","filePath":"3.x/ru/markup/tag/if.md"}'),u={name:"3.x/ru/markup/tag/if.md"};function d(r,a,g,k,m,w){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[s(t),a[0]||(a[0]=i("h1",null,"{% if %}",-1)),s(e),a[1]||(a[1]=c(`<p>Теги <code>{% if %}</code> и <code>{% endif %}</code> представляют выражение и аналогичны операторам if в PHP. В простейшей форме можно проверить, вычисляется ли выражение как <code>true</code>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> online <span class="token operator">==</span> <span class="token boolean">false</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The website is in maintenance mode.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы также можете проверить, не пуст ли массив:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> users <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> user <span class="token operator">in</span> users <span class="token delimiter punctuation">%}</span></span>
            <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user<span class="token punctuation">.</span>username <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><blockquote><p><strong>Примечание</strong>: Если вы хотите проверить, определена ли переменная, используйте <code>{% if users is defined %}</code>.</p></blockquote><p>Вы также можете использовать <code>not</code> для проверки значений, вычисляемых как <code>false</code>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> <span class="token operator">not</span> user<span class="token punctuation">.</span>subscribed <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>You are not subscribed to our mailing list.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Для множественных выражений можно использовать <code>{% elseif %}</code> и <code>{% else %}</code>:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> kenny<span class="token punctuation">.</span>sick <span class="token delimiter punctuation">%}</span></span>
    Kenny is sick.
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">elseif</span> kenny<span class="token punctuation">.</span>dead <span class="token delimiter punctuation">%}</span></span>
    You killed Kenny! You bastard!!!
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    Kenny looks okay so far.
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="правила-выражении"><a href="#правила-выражении" class="header-anchor">#</a> Правила выражений</h2><p>Правила определения истинности или ложности выражения такие же, как в PHP. Вот граничные случаи:</p><div class="table"><table tabindex="0"><thead><tr><th>Значение</th><th>Логическое вычисление</th></tr></thead><tbody><tr><td><em>пустая строка</em></td><td>false</td></tr><tr><td><em>числовой ноль</em></td><td>false</td></tr><tr><td><em>строка только из пробелов</em></td><td>true</td></tr><tr><td><em>пустой массив</em></td><td>false</td></tr><tr><td><em>null</em></td><td>false</td></tr><tr><td><em>непустой массив</em></td><td>true</td></tr><tr><td><em>объект</em></td><td>true</td></tr></tbody></table></div>`,12))])}const y=p(u,[["render",d]]);export{_ as __pageData,y as default};
